effect.shader:
#define PI 3.14159265359
float luma(vec3 c){ return dot(c,vec3(0.2126,0.7152,0.0722)); }
vec4 tex(vec2 uv){
return texture2DCv(inputImg.texture, clamp(uv,0.0,1.0));
}
vec3 texRGB(vec2 uv){ return tex(uv).rgb; }
vec3 rgb2hsv(vec3 c){
vec4 K=vec4(0.0,-1.0/3.0,2.0/3.0,-1.0);
vec4 p=mix(vec4(c.bg,K.wz),vec4(c.gb,K.xy),step(c.b,c.g));
vec4 q=mix(vec4(p.xyw,c.r),vec4(c.r,p.yzx),step(p.x,c.r));
float d=q.x-min(q.w,q.y);
return vec3(abs(q.z+(q.w-q.y)/(6.0*d+1e-10)),d/(q.x+1e-10),q.x);
}
float getHeight(vec2 uv){
vec4 c = tex(uv);
float h;
if(heightSource==0)      h = luma(c.rgb);
else if(heightSource==1) h = c.r;
else if(heightSource==2) h = c.g;
else if(heightSource==3) h = c.b;
else if(heightSource==4) h = c.a;
else                     h = rgb2hsv(c.rgb).y;
return invertHeight ? 1.0-h : h;
}
float getHeightSmooth(vec2 uv, vec2 ts){
if(!smoothNormal) return getHeight(uv);
float acc=0.0, ws=0.0;
for(float x=-1.0;x<=1.0;x+=1.0){
for(float y=-1.0;y<=1.0;y+=1.0){
float w=exp(-(x*x+y*y)*0.5);
acc+=getHeight(uv+vec2(x,y)*ts)*w;
ws +=w;
}
}
return acc/ws;
}
vec3 computeNormal(vec2 uv){
vec2 ts = 1.0 / acScreenSize * sampleRadius;
float tl = getHeightSmooth(uv+vec2(-ts.x, ts.y), ts);
float t  = getHeightSmooth(uv+vec2(   0.0, ts.y), ts);
float tr = getHeightSmooth(uv+vec2( ts.x, ts.y), ts);
float l  = getHeightSmooth(uv+vec2(-ts.x,  0.0), ts);
float r  = getHeightSmooth(uv+vec2( ts.x,  0.0), ts);
float bl = getHeightSmooth(uv+vec2(-ts.x,-ts.y), ts);
float b  = getHeightSmooth(uv+vec2(   0.0,-ts.y), ts);
float br = getHeightSmooth(uv+vec2( ts.x,-ts.y), ts);
float dX = (-tl - 2.0*l - bl + tr + 2.0*r + br);
float dY = (-tl - 2.0*t - tr + bl + 2.0*b  + br);
dX *= strength;
dY *= strength;
vec3 normal = normalize(vec3(-dX, dY, 1.0));
return normal;
}
vec3 applyLighting(vec3 normal, vec3 albedo){
vec3 lightDir = normalize(vec3(lightX, lightY, lightZ));
float NdL     = max(dot(normal, lightDir), 0.0);
vec3  viewDir = vec3(0.0, 0.0, 1.0);
vec3  halfDir = normalize(lightDir + viewDir);
float NdH     = max(dot(normal, halfDir), 0.0);
float spec    = pow(NdH, specPower) * specular;
vec3 lCol  = vec3(lightColor.r,  lightColor.g,  lightColor.b);
vec3 aCol  = vec3(ambientColor.r, ambientColor.g, ambientColor.b);
vec3 result = albedo * (aCol * ambient + lCol * NdL)
+ lCol * spec;
return clamp(result, 0.0, 1.0);
}
void main(){
vec2 uv      = acScreenNorm;
vec4 srcTex  = tex(uv);
vec3 original = srcTex.rgb / max(srcTex.a, 0.001);
vec3 normal  = computeNormal(uv);
vec3 normalRGB = normal * 0.5 + 0.5;
vec2  ts       = 1.0/acScreenSize*sampleRadius;
float height   = getHeightSmooth(uv, ts);
vec3  heightRGB = vec3(height);
vec3 result;
if(outputMode == 0){
result = normalRGB;
} else if(outputMode == 1){
result = applyLighting(normal, original);
} else if(outputMode == 2){
result = heightRGB;
} else if(outputMode == 3){
vec3 lit = applyLighting(normal, original);
result   = mix(original, lit, 0.7);
result   = mix(result, normalRGB, 0.3);
} else {
result = applyLighting(normal, vec3(0.8));
}
result = mix(original, result, mixAmount);
result = clamp(result, 0.0, 1.0);
gl_FragColor = vec4(result, srcTex.a) * srcTex.a;
}
